#include <stdio.h>

int main(void) {
    // Напишите решение здесь.
    return 0;
}

additionalExercises.referenceSolution:
#include <stdio.h>
#include <string.h>

int main(void) {
    char line[256];
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\r\n")] = '\0';
        int stack[256];
        int size = 0;
        int error = 0;
        for (int i = 0; line[i] != '\0' && error == 0; i++) {
            char c = line[i];
            if (c == '(' || c == '[' || c == '{') {
                stack[size++] = i;
            } else if (c == ')' || c == ']' || c == '}') {
                char open = c == ')' ? '(' : c == ']' ? '[' : '{';
                if (size == 0 || line[stack[size - 1]] != open) {
                    error = i + 1;
                } else {
                    size--;
                }
            }
        }
        if (error == 0 && size > 0) {
            error = stack[0] + 1;
        }
        if (error == 0) {
            printf("да\n");
        } else {
            printf("ошибка %d\n", error);
        }
    }
    return 0;
}

