#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char line[256];
    while (fgets(line, sizeof line, stdin) != NULL) {
        long long stack[128];
        int size = 0;
        int ok = 1;
        for (char *token = strtok(line, " \r\n"); token != NULL; token = strtok(NULL, " \r\n")) {
            if (strlen(token) == 1 && strchr("+-*", token[0]) != NULL) {
                long long b = stack[--size];
                long long a = stack[--size];
                stack[size++] = token[0] == '+' ? a + b : token[0] == '-' ? a - b : a * b;
            } else {
                if (size == 128) {
                    ok = 0;
                    break;
                }
                stack[size++] = strtoll(token, NULL, 10);
            }
        }
        if (ok && size == 1) {
            printf("%lld\n", stack[0]);
        } else {
            printf("ошибка\n");
        }
    }
    return 0;
}

