#include <stdio.h>

static int values[100000], answer[100000], stack[100000];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100000) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
        answer[i] = -1;
    }
    int size = 0;
    for (int i = 0; i < n; i++) {
        while (size > 0 && values[stack[size - 1]] < values[i]) {
            answer[stack[--size]] = values[i];
        }
        stack[size++] = i;
    }
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d\n", answer[i]);
    }
    return 0;
}

